from collections import deque, defaultdict

def can_finish(n, prerequisites):
    graph = defaultdict(list)          # pre -> [courses]
    indeg = [0] * n                    # 还欠多少门先修
    for course, pre in prerequisites:  # 输入是 (后修, 先修)
        graph[pre].append(course)      # 边顺着依赖走
        indeg[course] += 1             # 入度加在被指向的课上
    q = deque(i for i in range(n) if indeg[i] == 0)
    done = 0
    while q:
        cur = q.popleft(); done += 1
        for nxt in graph[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                q.append(nxt)
    return done == n                   # 计数不足 n 即有环

from collections import deque

def exchange_rate(graph, source, target):
    if source == target:
        return 1.0                      # 浮点字面量，别写 1
    seen = {source}
    q = deque([(source, 1.0)])          # (币种, 累积汇率) 二元组
    while q:
        cur, rate = q.popleft()
        if cur == target:
            return rate
        for nxt, edge in graph[cur]:
            if nxt not in seen:
                seen.add(nxt)           # 入队即标记，防重复入队
                q.append((nxt, rate * edge))
    return -1                           # 无路径的哨兵值

def search(nums, target):
    left, right = 0, len(nums) - 1     # 闭区间 [left, right]
    while left <= right:               # 三处配套之一
        mid = left + (right - left) // 2   # 防大数溢出
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1             # 必须 +1，写 mid 会死循环
        else:
            right = mid - 1            # 必须 -1
    return -1

class TrieNode:
    def __init__(self):
        self.children = {}      # char -> TrieNode
        self.is_end = False     # 标记完整词的末尾

def insert(root, word):
    node = root
    for ch in word:
        if ch not in node.children:      # 关键：先查再建
            node.children[ch] = TrieNode()
        node = node.children[ch]         # 复用已有子树
    node.is_end = True                   # 词尾标记，别漏

class MyDict:
    def __init__(self, size=1024):
        self.size = size
        self.buckets = [[] for _ in range(size)]   # 每桶一条链

    def _idx(self, key):
        return hash(key) % self.size               # 哈希 → 下标

    def get(self, key, default=None):
        for k, v in self.buckets[self._idx(key)]:  # 桶内比对 key
            if k == key:
                return v
        return default

    def put(self, key, value):
        b = self.buckets[self._idx(key)]
        for i, (k, _) in enumerate(b):
            if k == key:
                b[i] = (key, value)                # 已存在则更新
                return
        b.append((key, value))                     # 否则追加

def insert_path(root, dotted, value):
    path = dotted.split('.')          # "contact.phone.area" -> 三段
    node = root
    for key in path[:-1]:             # 除最后一段外逐层下潜
        node = node.setdefault(key, {})   # 没有就建，有就复用
    node[path[-1]] = value            # 最后一段才写值

def serialize_form(fields):
    result = {}
    for name, value in fields:
        insert_path(result, name, value)
    return result
